import pathlib,csv,subprocess
for f,a,b in [('PROJECT_HANDOFF.md',104,134),('tmp/pdfs/review/a313-3/e4/p152.csv',196,213),('tmp/pdfs/review/a313-3/e4/p150.csv',5,6)]:
 for i,line in enumerate(pathlib.Path(f).read_text(encoding='utf-8-sig').splitlines(),1):
  if a<=i<=b:print(f'{f}:{i}:{line}')
base=pathlib.Path('tmp/pdfs/review/a313-3/e4')
for name in ['p150.csv','p151.csv','p152.csv']:
 rows=list(csv.DictReader((base/name).open(encoding='utf-8-sig')))
 for u in range(1,8):
  tables=sorted(set(r['table'] for r in rows if r['table'].startswith(chr(0x423)+str(u)+chr(0x41f))))
  for t in tables:
   pins=[int(r['pin']) for r in rows if r['table']==t]
   expected=70 if t.endswith('3') else 53
   assert len(pins)==len(set(pins))==expected and set(pins)==set(range(1,expected+1)),t
   print('PIN_COVERAGE_OK',name,t,expected)
print('INLINE_ASSERTS_PASS')
'@ | python -B -; git status --short"

